"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def slidingWindowMax(arr, k):
    result = []
    deque = []
    # stores indices
    for i in range(0, len(arr)):
        while ((len(deque) > 0) and (deque[0] < ((i - k) + 1))):
            deque.pop(0)
        while ((len(deque) > 0) and (arr[deque[(-1)]] < arr[i])):
            deque.pop()
        deque.append(i)
        if (i >= (k - 1)):
            result.append(arr[deque[0]])
    return result
